{% set page_width = "215.9mm" %}
{% set page_height = "279.4mm" %}
{% set cell_width = "107.95mm" %}
{% set cell_height = "139.7mm" %}

<style>
    @page {
        size: 215.9mm 279.4mm;
        margin: 0;
    }
    body {
        margin: 0;
        padding: 0;
        font-family: Arial, Helvetica, sans-serif;
    }
    .label-sheet {
        width: 215.9mm;
        height: 279.4mm;
        display: flex;
        flex-wrap: wrap;
        align-content: flex-start;
        padding: 0;
        margin: 0;
        box-sizing: border-box;
    }
    .label-cell {
        width: 107.95mm;
        height: 139.7mm;
        box-sizing: border-box;
        position: relative;
        overflow: hidden;
    }
    .label-content {
        /* Full content zone for blank labels - no preprinted areas to avoid */
        position: absolute;
        top: 8mm;
        left: 8mm;
        right: 8mm;
        bottom: 8mm;
        font-size: 8pt;
        line-height: 1.3;
        display: flex;
        flex-direction: column;
        gap: 2mm;
    }
    .label-content .field-label {
        font-weight: bold;
        font-size: 6pt;
        color: #444;
        text-transform: uppercase;
        margin: 0;
        line-height: 1.2;
    }
    .label-content .field-value {
        font-size: 9pt;
        color: #000;
        margin: 0;
        line-height: 1.2;
    }
    .label-content .item-name {
        font-size: 10pt;
        font-weight: bold;
        color: #1a5c2a;
        margin: 0;
        line-height: 1.2;
    }
    .label-content .customer-name {
        font-size: 10pt;
        font-weight: bold;
        margin: 0;
        line-height: 1.2;
    }
    .label-content .section {
        margin-bottom: 1mm;
    }
    .label-content .row {
        display: flex;
        justify-content: space-between;
        margin-bottom: 1mm;
    }
    .label-content .row .field {
        flex: 1;
    }
    .label-content .row .field:not(:last-child) {
        margin-right: 3mm;
    }
</style>

<div class="label-sheet">
    {# Repeat the same label 4 times (2x2 grid) #}
    {% for i in range(4) %}
    <div class="label-cell">
        <div class="label-content">
            <div class="section">
                <div class="customer-name">{{ doc.customer_name or doc.customer }}</div>
            </div>

            <div class="section">
                <div class="row">
                    <div class="field">
                        <div class="field-label">Sales Order</div>
                        <div class="field-value">{{ doc.name }}</div>
                    </div>
                    <div class="field">
                        <div class="field-label">Date</div>
                        <div class="field-value">{{ doc.transaction_date | default("") }}</div>
                    </div>
                </div>
            </div>

            <div class="section">
                <div class="row">
                    <div class="field">
                        <div class="field-label">Delivery</div>
                        <div class="field-value">{{ doc.delivery_date | default("") }}</div>
                    </div>
                    <div class="field">
                        <div class="field-label">PO No.</div>
                        <div class="field-value">{{ doc.po_no or "N/A" }}</div>
                    </div>
                </div>
            </div>

            {% if doc.items %}
            {% set item = doc.items[0] %}
            <div class="section">
                <div class="item-name">{{ item.item_name or item.item_code }}</div>
                <div class="row">
                    <div class="field">
                        <div class="field-label">Code</div>
                        <div class="field-value">{{ item.item_code }}</div>
                    </div>
                    <div class="field">
                        <div class="field-label">Qty</div>
                        <div class="field-value">{{ item.qty }} {{ item.uom }}</div>
                    </div>
                </div>
                {% if item.description %}
                <div class="field-label">Description</div>
                <div class="field-value" style="font-size: 7pt;">{{ item.description | truncate(80) }}</div>
                {% endif %}
            </div>
            {% endif %}
        </div>
    </div>
    {% endfor %}
</div>

{% set page_width = "215.9mm" %}
{% set page_height = "279.4mm" %}
{% set cell_width = "107.95mm" %}
